CREATE TABLE workflow_children (
    child_task_id       TEXT PRIMARY KEY REFERENCES tasks(task_id) ON DELETE RESTRICT,
    parent_run_id       TEXT NOT NULL REFERENCES workflow_runs(run_id) ON DELETE RESTRICT,
    request_id          TEXT NOT NULL,
    decision_command_id TEXT NOT NULL,
    role                TEXT NOT NULL DEFAULT 'helper',
    integrator          INTEGER NOT NULL DEFAULT 0,
    state               TEXT NOT NULL CHECK (state IN ('active','succeeded','failed','cancelled','attention')),
    workspace_manifest_json TEXT,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL
);
INSERT INTO "workflow_children" VALUES('00000000-0000-0000-0000-0000000000b5','00000000-0000-0000-0000-00000000009a','req-00000000-0000-0000-0000-0000000000b1','approve-fixture-helper','helper',0,'succeeded','{"access":"read","baseCommit":"122ec20edcdeb97cc655ae3993c402c2c9c966a3","checkoutId":"54f20e7a1bdfc98273a46279774d95b2775bedaf1317b37fcc397a6ed69801a1","checkoutRoot":"<fixture-root>/workspaces/failed","exclusionPolicy":{"kind":"git-standard","managedPaths":"tracked-and-nonignored-untracked","selectedIgnored":"includeUntracked","version":1},"inputCommit":"122ec20edcdeb97cc655ae3993c402c2c9c966a3","inputTree":"d58371e8d82e8b661f800dc32247a3ccd6d414c9","integrator":{"id":"fixture-host","role":"host"},"kind":"existing","manifestSha256":"861807f576a6fbe7b30e965c0614a871af7a32d6fa8bfb0a1009008f6b9295db","path":"<fixture-root>/workspaces/failed","repositoryId":"dbaa625c7184b7964ab48d9236a04ee6bce7c824996340a2b0a23fefe12f1083","snapshot":{"excludedEntries":{},"excludedUntracked":[],"executionFingerprint":"e856f04e8d9a0c4b8eebfdfb5dcb18cd6dab76f3e919d181b749ae8dcef86f64","executionSelectors":[],"includeSelectors":[],"includedUntracked":[],"inputRef":"refs/hey-my-buddy/workspaces/ws-49891c804ef91e897a016e9a071fae72/input","repositoryPath":"<fixture-root>/repository/.git","sourceCheckoutId":"54f20e7a1bdfc98273a46279774d95b2775bedaf1317b37fcc397a6ed69801a1","sourceFingerprint":"e856f04e8d9a0c4b8eebfdfb5dcb18cd6dab76f3e919d181b749ae8dcef86f64","sourceHead":"122ec20edcdeb97cc655ae3993c402c2c9c966a3","stagedCommit":"122ec20edcdeb97cc655ae3993c402c2c9c966a3","stagedRef":"refs/hey-my-buddy/workspaces/ws-49891c804ef91e897a016e9a071fae72/staged","stagedTree":"d58371e8d82e8b661f800dc32247a3ccd6d414c9"},"targetRef":null,"version":3,"workspaceId":"ws-49891c804ef91e897a016e9a071fae72","writeScope":[]}','2026-01-01T00:00:00.000Z','2026-01-01T00:01:00.000Z');
CREATE TABLE workflow_continuations (
    continuation_id   TEXT PRIMARY KEY,
    run_id            TEXT NOT NULL REFERENCES workflow_runs(run_id) ON DELETE RESTRICT,
    command_id        TEXT,
    kind              TEXT NOT NULL CHECK (kind IN ('manual','helper','lead-wakeup')),
    request_id        TEXT,
    trigger_event_json TEXT,
    expected_revision INTEGER NOT NULL,
    input_text        TEXT NOT NULL,
    note              TEXT,
    helper_policy     TEXT NOT NULL DEFAULT 'keep' CHECK (helper_policy IN ('cancel','keep')),
    helper_outcomes_json TEXT NOT NULL DEFAULT '[]',
    workspace_manifest_json TEXT,
    state             TEXT NOT NULL CHECK (state IN ('recorded','queued','consumed','cancelled','invalidated')),
    attempt_id        TEXT,
    turn_id           TEXT,
    created_at        TEXT NOT NULL,
    consumed_at       TEXT,
    CHECK ((kind IN ('manual','helper') AND trigger_event_json IS NULL)
        OR (kind='lead-wakeup' AND trigger_event_json IS NOT NULL
            AND json_valid(trigger_event_json) AND json_type(trigger_event_json)='object'))
);
