INSERT INTO "workflow_host_conclusions" VALUES('conclusion-00000000-0000-0000-0000-0000000000de','00000000-0000-0000-0000-00000000009a','00000000-0000-0000-0000-0000000000d1',12,1,'cancelled','Fixture Host concluded helper parent',NULL,NULL,'00000000-0000-0000-0000-0000000000d9','host','fixture-host','conclude-94a1831eed5d342a7a37f44a4e704e3a','2026-01-01T00:01:00.000Z');
CREATE TABLE workflow_integrations (
    integration_id        TEXT PRIMARY KEY,
    run_id                TEXT NOT NULL REFERENCES workflow_runs(run_id) ON DELETE RESTRICT,
    artifact_id           TEXT NOT NULL,
    strategy              TEXT NOT NULL,
    binding_sha256        TEXT NOT NULL,
    target_path           TEXT NOT NULL DEFAULT '',
    target_ref            TEXT NOT NULL DEFAULT '',
    target_repository_id  TEXT,
    target_checkout_id    TEXT,
    source_commit         TEXT,
    source_tree           TEXT,
    before_commit         TEXT,
    after_commit          TEXT,
    before_tree           TEXT,
    after_tree            TEXT,
    verification_json     TEXT NOT NULL,
    note                  TEXT,
    command_id            TEXT,
    actor_role            TEXT NOT NULL,
    actor_id              TEXT NOT NULL,
    created_at            TEXT NOT NULL,
    CHECK (actor_role IN ('host','lead','console','service','workflow','bridge')),
    UNIQUE(binding_sha256)
);
